import { defineConfig } from "astro/config";
import sitemap from "@astrojs/sitemap";
import { readdirSync, readFileSync, existsSync } from "node:fs";

// Collect `redirectFrom` ids from blog post frontmatter so the redirect stubs
// generated by src/pages/blog/[id].astro are left out of the sitemap.
// Supports `redirectFrom: old-id`, `redirectFrom: [a, b]` and YAML list form.
function blogRedirectSources() {
  const dir = "./src/content/blog";
  const sources = new Set();
  for (const entry of readdirSync(dir)) {
    const file = `${dir}/${entry}/index.md`;
    if (!existsSync(file)) continue;
    const frontmatter =
      readFileSync(file, "utf-8").match(/^---\n([\s\S]*?)\n---/)?.[1] ?? "";
    const match = frontmatter.match(
      /^redirectFrom:[ \t]*(.*)\n?((?:[ \t]+-.*\n?)*)/m,
    );
    if (!match) continue;
    const values = match[1].trim()
      ? match[1].replace(/^\[|\]$/g, "").split(",")
      : match[2].split("\n").map((line) => line.replace(/^\s*-/, ""));
    for (const value of values) {
      const id = value.trim().replace(/^["']|["']$/g, "");
      if (id) sources.add(id);
    }
  }
  return sources;
}

const redirectSources = blogRedirectSources();

export default defineConfig({
  site: "https://elifepathways.org",
  base: "/",
  devToolbar: { enabled: false },
  vite: {
    server: {
      allowedHosts: ["host.docker.internal"],
    },
  },
  integrations: [
    sitemap({
      filter: (page) => {
        const id = new URL(page).pathname.match(/^\/blog\/([^/]+)\/?$/)?.[1];
        return !(id && redirectSources.has(id));
      },
    }),
  ],
});
